import java.util.Arrays;
import java.util.Random;

public class QuickSort {

    public static <T extends Comparable<T>> void quickSort(T[] arr) {
        if (arr == null || arr.length < 2) {
            return;
        }
        quickSortRecursive(arr, 0, arr.length - 1);
    }

    private static <T extends Comparable<T>> void quickSortRecursive(T[] arr, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(arr, low, high);
            quickSortRecursive(arr, low, pivotIndex - 1);
            quickSortRecursive(arr, pivotIndex + 1, high);
        }
    }

    private static <T extends Comparable<T>> int partition(T[] arr, int low, int high) {
        Random random = new Random();
        int pivotIndex = low + random.nextInt(high - low + 1);
        T pivot = arr[pivotIndex];
        swap(arr, pivotIndex, high);

        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j].compareTo(pivot) < 0) {
                i++;
                swap(arr, i, j);
            }
        }
        swap(arr, i + 1, high);
        return i + 1;
    }

    private static <T> void swap(T[] arr, int i, int j) {
        T temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        Integer[] arr = {10, 7, 8, 9, 1, 5};
        System.out.println("Unsorted array: " + Arrays.toString(arr));
        quickSort(arr);
        System.out.println("Sorted array: " + Arrays.toString(arr));

        String[] strArr = {"banana", "apple", "orange", "grape"};
        System.out.println("\nUnsorted string array: " + Arrays.toString(strArr));
        quickSort(strArr);
        System.out.println("Sorted string array: " + Arrays.toString(strArr));
    }
}
