public class QuickSort<T extends Comparable<T>> { // Generic type declaration moved here

    private final Random random = new Random(); // Random object created once

    public void quickSort(T[] arr) {
        if (arr == null || arr.length < 2) {
            return;
        }
        quickSortRecursive(arr, 0, arr.length - 1);
    }

    private void quickSortRecursive(T[] arr, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(arr, low, high);
            quickSortRecursive(arr, low, pivotIndex - 1);
            quickSortRecursive(arr, pivotIndex + 1, high);
        }
    }

    private int partition(T[] arr, int low, int high) {
        int pivotIndex = low + random.nextInt(high - low + 1);
        T pivot = arr[pivotIndex];
        swap(arr, pivotIndex, high); //Using the improved swap method below

        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (arr[j].compareTo(pivot) < 0) {
                i++;
                swap(arr, i, j); //Using the improved swap method below
            }
        }
        swap(arr, i + 1, high); //Using the improved swap method below
        return i + 1;
    }


    //Improved Swap method
